+    this.calls++;
+    const generation = this.generation;
+    return this.backend.serial(async () => {
+      guard();
+      await this.beforeCommit?.();
+      if (this.fault) throw this.fault;
+      if (generation !== this.generation) throw new DOMException('synthetic', 'AbortError');
+      guard();
