+export const SAVED_NATAL_RECORD_SCHEMA = 'zodiacs.saved-natal.v1';
+export const MAX_SAVED_NATAL_RECORDS = 40;
+export const MAX_SAVED_NATAL_LABEL_CODE_POINTS = 120;
