+    if (fields.schema !== SAVED_NATAL_RECORD_SCHEMA || fields.ownerKey !== ownerKey
+      || !isSavedNatalId(fields.id) || !validTimestamp(fields.createdAt)
+      || !validLabel(fields.label) || (Object.hasOwn(fields, 'label') && fields.label === undefined)
